(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  for (let i = 0; i < 300 && !window.__luminati?.loadMs; i++) await sleep(100);
  const failed = [];
  const CC = window.CC = {
    sleep, failed,
    until: async (fn, ms = 15000) => { const t0 = performance.now(); while (performance.now() - t0 < ms) { if (fn()) return true; await sleep(100); } return false; },
    expect: (ok, label, detail) => { if (ok) return true; const t = `campaign.cleared: ${label}${detail !== undefined ? ' — ' + JSON.stringify(detail) : ''}`; failed.push(t); setTimeout(() => { throw new Error(t); }); return false; },
    save: () => JSON.parse(localStorage.getItem('luminati.campaign.ferrymans-lantern')),
    floor: ['slimes_floor#0', 'slimes_floor#1', 'slimes_floor#2'],
    floorState: () => window.__game.combat.system.enemies.filter((e) => e.groupId === 'slimes_floor').map((e) => `${e.uid}:${e.alive ? 'alive' : 'dead'}:${e.sprite.visible ? 'shown' : 'hidden'}`),
    play: () => CC.until(() => window.__game.game.mode === 'play' && !window.__game.state().campaign.traveling),
    idle: async () => { await window.__game.game.story?.whenIdle?.(); await sleep(200); },
  };
  window.__game.story.auto(true);
  const ok = await window.__game.campaign.travel('old-quarry', '');
  await CC.play();
  await CC.idle();
  const c = window.__game.combat;
  const st = c.state();
  CC.expect(ok && window.__game.state().campaign.level === 'old-quarry', 'travelled to the quarry');
  CC.expect(st.enemies.alive === 6 && st.enemies.total === 6, 'six slimes on the first visit', st.enemies);
  return JSON.stringify({ ok, level: window.__game.state().campaign.level, enemies: st.enemies, uids: c.enemies().map((e) => e.uid), cleared: CC.save()?.cleared });
})()

(async () => {
  const c = window.__game.combat;
  const sys = c.system;
  const xp0 = c.state().player.xp;
  for (const uid of CC.floor) c.kill(uid);
  await CC.sleep(400);
  await CC.idle();
  const st = c.state();
  CC.expect(sys.defeatedGroups().join() === 'slimes_floor', 'the floor pack is defeated', sys.defeatedGroups());
  CC.expect(st.kills === 3 && st.player.xp > xp0, 'kills and XP of the first defeat', { kills: st.kills, xp: st.player.xp, xp0 });
  CC.xpAfterKill = st.player.xp;
  CC.levelAfterKill = st.player.level;
  return JSON.stringify({ defeated: sys.defeatedGroups(), kills: st.kills, xp0, xp: st.player.xp, level: st.player.level, alive: st.enemies.alive, storyDone: window.__game.story.info?.()?.done ?? null });
})()

