(async () => {
  const ok = await window.__game.campaign.travel('old-quarry', '');
  await CC.play();
  await CC.sleep(600);
  const c = window.__game.combat;
  const sys = c.system;
  const st = c.state();
  const story = window.__game.game.story;
  CC.expect(st.enemies.alive === 3 && st.enemies.total === 6, 'the defeated pack is not back', st.enemies);
  CC.expect(CC.floorState().every((s) => s.endsWith(':dead:hidden')), 'its slimes are fallen and not drawn', CC.floorState());
  CC.expect(st.kills === 0 && st.pickups === 0, 'no kill, no drop on entering', { kills: st.kills, pickups: st.pickups });
  CC.expect(st.player.xp === CC.xpAfterKill && st.player.level === CC.levelAfterKill, 'no XP on entering', { xp: st.player.xp, was: CC.xpAfterKill });
  CC.expect(!story.run && story.queue.length === 0, 'no story run (the cleared event does not fire again)', { run: !!story.run, queue: story.queue.length });
  CC.expect(sys.defeatedGroups().join() === 'slimes_floor', 'still defeated', sys.defeatedGroups());
  return JSON.stringify({ ok, enemies: st.enemies, floor: CC.floorState(), kills: st.kills, pickups: st.pickups, xp: st.player.xp, run: !!story.run, queue: story.queue.length, defeated: sys.defeatedGroups() });
})()

(async () => {
  const c = window.__game.combat;
  const sys = c.system;
  const rested = c.rest('waystone');
  await CC.sleep(300);
  const st = c.state();
  CC.expect(rested && st.enemies.alive === 6, 'a waystone rest brings the pack back', st.enemies);
  CC.expect(CC.floorState().every((s) => s.endsWith(':alive:shown')), 'its slimes are back home', CC.floorState());
  CC.expect(sys.defeatedGroups().length === 0, 'nothing defeated after the rest', sys.defeatedGroups());
  window.__game.campaign.save();
  const save = CC.save();
  CC.expect(!save.cleared['old-quarry'], 'the rest clears the level\'s list', save.cleared);
  return JSON.stringify({ rested, enemies: st.enemies, floor: CC.floorState(), cleared: save.cleared });
})()

